DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.hc_action(uuid,uuid,uuid,text,jsonb)'::regprocedure) INTO definition; definition := replace(definition, 'SELECT encode(bytes,''base64'') INTO result FROM public.hc_chunks WHERE transfer_id=tr.id AND position=(p_data->>''position'')::integer;', '-- Binary is projected only through jsonb_build_object below.'); EXECUTE definition; END $$;